/**
 * Generate plugins/types/index.d.ts from src/client/PluginApi/index.ts
 *
 * Every type `@client/PluginApi` exports, and ClientEvents
 * (src/shared/events/clientEvents.ts), is emitted with every type it
 * references, straight from its source declaration. Classes get a declaration
 * of their public members (minus those tagged `@internal`). Only what has no
 * source in this project (MapRenderer, MapData, Client) is written out here.
 * The result must compile on its own or the script fails.
 */

const ts = require('typescript');
const fs = require('fs');
const path = require('path');

const PROJECT_ROOT = path.resolve(__dirname, '..', '..');
const SOURCE_FILE = path.join(PROJECT_ROOT, 'src', 'client', 'PluginApi', 'index.ts');
const EVENTS_FILE = path.join(PROJECT_ROOT, 'src', 'shared', 'events', 'clientEvents.ts');
const OUTPUT_FILE = path.join(__dirname, 'index.d.ts');
const TSCONFIG_PATH = path.join(PROJECT_ROOT, 'tsconfig.json');

console.log('🔧 Generating plugin types from source...');
console.log(`📄 Source: ${path.relative(PROJECT_ROOT, SOURCE_FILE)}`);
console.log(`📝 Output: ${path.relative(PROJECT_ROOT, OUTPUT_FILE)}`);

// Read tsconfig
const configFile = ts.readConfigFile(TSCONFIG_PATH, ts.sys.readFile);
const parsedConfig = ts.parseJsonConfigFileContent(
  configFile.config,
  ts.sys,
  PROJECT_ROOT
);

// Create program
const program = ts.createProgram({
  rootNames: [SOURCE_FILE, EVENTS_FILE],
  options: {
    ...parsedConfig.options,
    declaration: true,
    emitDeclarationOnly: true,
    declarationDir: path.join(__dirname, '.temp'),
    noEmit: false
  }
});

const sourceFile = program.getSourceFile(SOURCE_FILE);
if (!sourceFile) {
  console.error('❌ Could not load source file');
  process.exit(1);
}

const checker = program.getTypeChecker();
const output = [];

// Header comment
output.push(`/**
 * TypeScript Type Definitions for Arkadia Web Client Plugins
 *
 * This package provides TypeScript type definitions for developing
 * plugins for the Arkadia Web Client.
 *
 * MAINTAINER NOTE: This file is AUTO-GENERATED from src/client/PluginApi/
 * Do not edit this file directly. Run 'yarn build:types' to regenerate.
 *
 * @packageDocumentation
 */
`);

// Track what we've already exported to avoid duplicates
const exportedTypes = new Set();

// Helper to get JSDoc comments (only the leading JSDoc before the node)
function getLeadingJsDoc(node) {
  const sf = node.getSourceFile();
  const fullText = node.getFullText(sf);
  const nodeText = node.getText(sf);
  const leading = fullText.substring(0, fullText.indexOf(nodeText));

  // Last JSDoc comment (/** ... */) - an earlier one belongs to a section, not this node
  const jsDocMatches = leading.match(/\/\*\*[\s\S]*?\*\//g);
  return jsDocMatches ? jsDocMatches[jsDocMatches.length - 1] : null;
}

// Helper to convert node to string (sf: the file the node, or its original, came from)
function nodeToString(node, sf) {
  const printer = ts.createPrinter({
    newLine: ts.NewLineKind.LineFeed,
    removeComments: false  // Keep comments for interface members
  });

  let result = printer.printNode(ts.EmitHint.Unspecified, node, sf);

  // Remove leading comments from the result (the JSDoc is added separately, a
  // stray line comment would otherwise end up between 'export' and the declaration)
  result = result.replace(/^(\s*)(?:(?:\/\*[\s\S]*?\*\/|\/\/[^\n]*)\s*)+/, '$1');

  // Remove 'export ' keyword if present (TypeScript printer adds it)
  result = result.replace(/^export\s+/, '');

  return result;
}

// ----------------------------------------------------------------------------
// Reachable types
//
// The roots (every type @client/PluginApi exports, plus ClientEvents) are
// emitted along with every project type they reference, transitively, so a
// type the API mentions can never be missing from the package. Types written
// out by hand below are skipped by name.
// ----------------------------------------------------------------------------

const SRC_DIR = path.join(PROJECT_ROOT, 'src') + path.sep;

// Plugins augment these with `declare module ... { interface X {...} }`, which
// only merges with an interface - a type alias is converted on the way out.
const AUGMENTABLE = new Set(['ClientEvents']);

// Ambient global namespaces from src/**/*.d.ts, inlined further down
const AMBIENT_NAMESPACES = new Set(['MapData']);

function isProjectSource(sf) {
  return !sf.isDeclarationFile && path.resolve(sf.fileName).startsWith(SRC_DIR);
}

function isReactDeclaration(sf) {
  return /[\\/]node_modules[\\/]@types[\\/]react[\\/]/.test(sf.fileName);
}

function resolveSymbol(id) {
  let symbol = checker.getSymbolAtLocation(id);
  if (symbol && symbol.flags & ts.SymbolFlags.Alias) symbol = checker.getAliasedSymbol(symbol);
  return symbol;
}

function leftmostIdentifier(name) {
  while (ts.isQualifiedName(name)) name = name.left;
  while (ts.isPropertyAccessExpression(name)) name = name.expression;
  return ts.isIdentifier(name) ? name : null;
}

function isEmittable(decl) {
  return ts.isInterfaceDeclaration(decl) || ts.isTypeAliasDeclaration(decl) || ts.isEnumDeclaration(decl) ||
    ts.isClassDeclaration(decl);
}

// ----------------------------------------------------------------------------
// Classes
//
// A class carries implementation and private state, so it is emitted as a
// declaration of its public surface: members that are not private, protected
// or tagged `@internal`. A class whose constructor is private or `@internal`
// is not for plugins to construct, and becomes an interface.
// ----------------------------------------------------------------------------

function isInternal(node) {
  return ts.getJSDocTags(node).some((tag) => tag.tagName.text === 'internal');
}

function isPublicMember(member) {
  if (member.name && ts.isPrivateIdentifier(member.name)) return false;
  const flags = ts.getCombinedModifierFlags(member);
  if (flags & (ts.ModifierFlags.Private | ts.ModifierFlags.Protected)) return false;
  return !isInternal(member);
}

// The member's own JSDoc, reattached to the synthesized declaration
function withJsDoc(node, original) {
  const jsDoc = getLeadingJsDoc(original);
  if (!jsDoc) return node;
  const body = jsDoc
    .slice(2, -2)
    .split('\n')
    // The printer indents the comment's lines to the member itself
    .map((line, i) => (i === 0 ? line : line.replace(/^\s*\*/, ' *').replace(/^\s*$/, ' ')))
    .join('\n');
  return ts.addSyntheticLeadingComment(node, ts.SyntaxKind.MultiLineCommentTrivia, body, true);
}

// A copy of a member or parameter name: the original would bring its leading
// comments along, and the JSDoc is reattached by withJsDoc
function freshName(name) {
  if (ts.isIdentifier(name)) return ts.factory.createIdentifier(name.text);
  if (ts.isStringLiteral(name)) return ts.factory.createStringLiteral(name.text);
  return name;
}

const keep = (modifiers, ...kinds) => {
  const kept = (modifiers ?? []).filter((m) => kinds.includes(m.kind));
  return kept.length ? kept : undefined;
};

// A parameter as a declaration states it: no modifiers, no default value
function declaredParameter(param) {
  const optional = param.questionToken ?? (param.initializer ? ts.factory.createToken(ts.SyntaxKind.QuestionToken) : undefined);
  return ts.factory.createParameterDeclaration(
    undefined, param.dotDotDotToken, freshName(param.name), optional, param.type, undefined
  );
}

function classMembers(decl, asInterface) {
  const members = [];
  const typed = (member, type) => {
    if (type) return true;
    problems.push(`${decl.name.text}.${member.name.getText()} (${describe(member)}) is public but has no type annotation - add one, or tag it @internal`);
    return false;
  };
  const ctor = decl.members.find((m) => ts.isConstructorDeclaration(m) && m.body);
  // Parameter properties: `constructor(public tag?: string)`
  for (const param of ctor?.parameters ?? []) {
    const flags = ts.getCombinedModifierFlags(param);
    const isProperty = flags & (ts.ModifierFlags.Public | ts.ModifierFlags.Readonly) &&
      !(flags & (ts.ModifierFlags.Private | ts.ModifierFlags.Protected));
    if (!isProperty || isInternal(param) || !typed(param, param.type)) continue;
    const modifiers = keep(param.modifiers, ts.SyntaxKind.ReadonlyKeyword);
    members.push(withJsDoc(asInterface
      ? ts.factory.createPropertySignature(modifiers, freshName(param.name), param.questionToken, param.type)
      : ts.factory.createPropertyDeclaration(modifiers, freshName(param.name), param.questionToken, param.type, undefined), param));
  }
  for (const member of decl.members) {
    if (!isPublicMember(member)) continue;
    const isStatic = ts.getCombinedModifierFlags(member) & ts.ModifierFlags.Static;
    if (isStatic && asInterface) continue;
    const modifiers = keep(member.modifiers, ts.SyntaxKind.StaticKeyword, ts.SyntaxKind.ReadonlyKeyword);
    let node;
    if (ts.isConstructorDeclaration(member)) {
      if (asInterface || !member.body) continue;
      node = ts.factory.createConstructorDeclaration(undefined, member.parameters.map(declaredParameter), undefined);
    } else if (ts.isPropertyDeclaration(member)) {
      if (!typed(member, member.type)) continue;
      node = asInterface
        ? ts.factory.createPropertySignature(modifiers, freshName(member.name), member.questionToken, member.type)
        : ts.factory.createPropertyDeclaration(modifiers, freshName(member.name), member.questionToken, member.type, undefined);
    } else if (ts.isMethodDeclaration(member)) {
      // Overloads: the signatures without a body are the public ones
      const overloaded = decl.members.some((m) => m !== member && ts.isMethodDeclaration(m) && m.name.getText() === member.name.getText());
      if (overloaded && member.body) continue;
      if (!typed(member, member.type)) continue;
      const params = member.parameters.map(declaredParameter);
      node = asInterface
        ? ts.factory.createMethodSignature(undefined, freshName(member.name), member.questionToken, member.typeParameters, params, member.type)
        : ts.factory.createMethodDeclaration(modifiers, undefined, freshName(member.name), member.questionToken, member.typeParameters, params, member.type, undefined);
    } else if (ts.isGetAccessorDeclaration(member)) {
      if (!typed(member, member.type)) continue;
      const settable = decl.members.some((m) => ts.isSetAccessorDeclaration(m) && m.name.getText() === member.name.getText() && isPublicMember(m));
      const readonly = settable ? modifiers : [...(modifiers ?? []), ts.factory.createModifier(ts.SyntaxKind.ReadonlyKeyword)];
      node = asInterface
        ? ts.factory.createPropertySignature(readonly, freshName(member.name), undefined, member.type)
        : ts.factory.createPropertyDeclaration(readonly, freshName(member.name), undefined, member.type, undefined);
    } else if (ts.isIndexSignatureDeclaration(member)) {
      node = member;
    } else {
      continue;
    }
    members.push(withJsDoc(node, member));
  }
  return members;
}

function classDeclaration(decl) {
  const ctor = decl.members.find((m) => ts.isConstructorDeclaration(m) && m.body);
  const asInterface = !!ctor && !isPublicMember(ctor);
  const heritage = decl.heritageClauses?.filter((h) => h.token === ts.SyntaxKind.ExtendsKeyword || !asInterface);
  const members = classMembers(decl, asInterface);
  const node = asInterface
    ? ts.factory.createInterfaceDeclaration(undefined, decl.name, decl.typeParameters, heritage, members)
    : ts.factory.createClassDeclaration(
        [ts.factory.createModifier(ts.SyntaxKind.DeclareKeyword)], decl.name, decl.typeParameters, heritage, members
      );
  return ts.setOriginalNode(node, decl);
}

// Names defined by the hand-written sections already in `output`
function handWrittenNames() {
  const names = new Set();
  for (const m of output.join('\n').matchAll(/^export (?:declare )?(?:interface|type|class|function|namespace|enum) (\w+)/gm)) {
    names.add(m[1]);
  }
  return names;
}

let provided = new Set();
const emitted = new Map();   // name -> symbol
const queue = [];
const problems = [];

function describe(node) {
  const sf = node.getSourceFile();
  const { line } = sf.getLineAndCharacterOfPosition(node.getStart(sf));
  return `${path.relative(PROJECT_ROOT, sf.fileName)}:${line + 1}`;
}

// A default export's symbol is called "default" - use the declared name
function symbolName(symbol) {
  const declared = symbol.declarations?.[0]?.name;
  return declared && ts.isIdentifier(declared) ? declared.text : symbol.getName();
}

function enqueue(symbol, from) {
  const name = symbolName(symbol);
  if (provided.has(name)) return;
  const known = emitted.get(name);
  if (known === symbol) return;
  if (known) {
    problems.push(`two different types are named ${name} (${describe(known.declarations[0])}, ${describe(symbol.declarations[0])})`);
    return;
  }
  const decls = symbol.declarations.filter(d => isProjectSource(d.getSourceFile()));
  if (!decls.length || !decls.every(isEmittable)) {
    problems.push(`${name} (${describe(symbol.declarations[0])}) is referenced from ${describe(from)} but is not an interface, type or enum - write it out by hand or change the reference`);
    return;
  }
  emitted.set(name, symbol);
  queue.push(...decls);
}

// Decide what a type reference refers to: a project type to emit (returns its
// declared name), a React type (`React.X`), or something that needs no output.
function classifyReference(id) {
  const symbol = resolveSymbol(id);
  if (!symbol || !symbol.declarations?.length) return null;
  if (symbol.flags & ts.SymbolFlags.TypeParameter) return null;
  const decl = symbol.declarations[0];
  const sf = decl.getSourceFile();
  if (isProjectSource(sf)) {
    enqueue(symbol, id);
    return symbolName(symbol);
  }
  if (isReactDeclaration(sf) && id.text !== 'React') return `React.${symbolName(symbol)}`;
  return null;
}

function referenceIdentifiers(node) {
  if (ts.isTypeReferenceNode(node)) return leftmostIdentifier(node.typeName);
  if (ts.isExpressionWithTypeArguments(node)) return leftmostIdentifier(node.expression);
  if (ts.isTypeQueryNode(node)) return leftmostIdentifier(node.exprName);
  return null;
}

// `typeof VALUE` has no value to point at in a types-only package. Resolve the
// smallest type around it that no longer needs the value - `keyof typeof X`,
// `(typeof X)[number]` - to what the checker computes, e.g. a literal union.
function valueQueryRoots(decl) {
  const roots = new Set();
  const visit = (node) => {
    if (ts.isTypeQueryNode(node)) {
      const id = leftmostIdentifier(node.exprName);
      const symbol = id && resolveSymbol(id);
      const sf = symbol?.declarations?.[0]?.getSourceFile();
      // A class is emitted, so `typeof SomeClass` can stay as it is
      if (sf && isProjectSource(sf) && !(symbol.flags & ts.SymbolFlags.Class)) {
        let root = node;
        while (ts.isParenthesizedTypeNode(root.parent) || ts.isIndexedAccessTypeNode(root.parent) ||
               (ts.isTypeOperatorNode(root.parent) && root.parent.operator === ts.SyntaxKind.KeyOfKeyword)) {
          root = root.parent;
        }
        roots.add(root);
      }
    }
    ts.forEachChild(node, visit);
  };
  visit(decl);
  return roots;
}

function resolvedTypeNode(node) {
  const flags = ts.NodeBuilderFlags.NoTruncation | ts.NodeBuilderFlags.InTypeAlias;
  const resolved = checker.typeToTypeNode(checker.getTypeFromTypeNode(node), undefined, flags);
  if (!resolved) problems.push(`could not resolve ${node.getText()} at ${describe(node)}`);
  return resolved ?? node;
}

// Rename references to their emitted names (`import {A as B}`, React types),
// resolve value queries, and collect the project types they point at
function rewriteReferences(root, valueRoots) {
  const result = ts.transform(root, [(context) => {
    const visit = (node) => {
      if (valueRoots.has(node)) return resolvedTypeNode(node);
      // import("@shared/x").Name -> Name, emitted like any other reference
      if (ts.isImportTypeNode(node) && !node.isTypeOf && node.qualifier && ts.isIdentifier(node.qualifier)) {
        const target = classifyReference(node.qualifier);
        if (target) {
          const typeArguments = node.typeArguments && ts.visitNodes(node.typeArguments, visit, context);
          return ts.factory.createTypeReferenceNode(target, typeArguments);
        }
      }
      const id = referenceIdentifiers(node);
      if (id) {
        const target = classifyReference(id);
        if (target && target !== id.text) {
          const swap = (n) => n === id
            ? ts.factory.createIdentifier(target)
            : ts.visitEachChild(n, swap, context);
          node = ts.visitEachChild(node, swap, context);
        }
      }
      return ts.visitEachChild(node, visit, context);
    };
    return (n) => ts.visitEachChild(n, visit, context);
  }]);
  return result.transformed[0];
}

// `type X = A & B & { ... }` -> `interface X extends A, B { ... }`
function aliasToInterface(decl) {
  const parts = ts.isIntersectionTypeNode(decl.type) ? decl.type.types : [decl.type];
  const heritage = [];
  const members = [];
  for (const part of parts) {
    if (ts.isTypeReferenceNode(part)) {
      heritage.push(ts.factory.createExpressionWithTypeArguments(part.typeName, part.typeArguments));
    } else if (ts.isTypeLiteralNode(part)) {
      members.push(...part.members);
    } else {
      problems.push(`${decl.name.text} (${describe(decl)}) must be an intersection of named types and type literals to become an interface`);
      return decl;
    }
  }
  const iface = ts.factory.createInterfaceDeclaration(
    decl.modifiers,
    decl.name,
    decl.typeParameters,
    heritage.length ? [ts.factory.createHeritageClause(ts.SyntaxKind.ExtendsKeyword, heritage)] : undefined,
    members
  );
  return ts.setOriginalNode(ts.setTextRange(iface, decl), decl);
}

function emitDeclaration(decl) {
  let node = decl;
  if (ts.isTypeAliasDeclaration(node) && AUGMENTABLE.has(node.name.text)) node = aliasToInterface(node);
  if (ts.isClassDeclaration(node)) node = classDeclaration(node);
  // Wrapped so the transform visits the declaration itself, heritage included
  node = rewriteReferences(ts.factory.createBlock([node]), valueQueryRoots(decl));
  const printed = node.statements.map((s) => nodeToString(s, decl.getSourceFile())).join('\n');
  const jsDoc = getLeadingJsDoc(decl);
  output.push('\n' + (jsDoc ? jsDoc + '\n' : '') + 'export ' + printed);
}

// Every type the module exports, re-exports included. A class counts only when
// exported with `export type`: a plain export of one is the implementation.
function exportedTypeSymbols(file) {
  const moduleSymbol = checker.getSymbolAtLocation(file);
  if (!moduleSymbol) return [];
  const exportedAsType = (alias) => alias.declarations?.some((d) =>
    ts.isExportSpecifier(d) && (d.isTypeOnly || d.parent.parent.isTypeOnly));
  return checker.getExportsOfModule(moduleSymbol)
    .map((alias) => ({ alias, symbol: alias.flags & ts.SymbolFlags.Alias ? checker.getAliasedSymbol(alias) : alias }))
    .filter(({ alias, symbol }) => symbol.flags & ts.SymbolFlags.Type &&
      (!(symbol.flags & ts.SymbolFlags.Value) || exportedAsType(alias)))
    .map(({ symbol }) => symbol);
}

function emitReachableTypes(roots, from) {
  provided = handWrittenNames();
  for (const symbol of roots) enqueue(symbol, from);
  for (let i = 0; i < queue.length; i++) {
    emitDeclaration(queue[i]);
  }
  for (const name of emitted.keys()) exportedTypes.add(name);
}

// Map renderer settings (MapRenderer.Settings, used by map overlays). The
// renderer's Settings.d.ts is self-contained, so it is copied verbatim into a
// namespace instead of making plugin-types depend on mudlet-map-renderer.
const rendererSettingsPath = path.join(
  PROJECT_ROOT, 'node_modules', 'mudlet-map-renderer', 'dist', 'types', 'Settings.d.ts'
);
const rendererSettings = fs.readFileSync(rendererSettingsPath, 'utf-8');
if (/^import /m.test(rendererSettings)) {
  console.error('❌ mudlet-map-renderer Settings.d.ts now has imports - update the MapRenderer namespace inlining');
  process.exit(1);
}
const rendererSettingsBody = rendererSettings
  // Runtime functions have no place in a types-only namespace
  .replace(/^export declare function[^\n]*\n?/gm, '')
  .replace(/^\/\/# sourceMappingURL=.*$/gm, '')
  .trimEnd()
  .split('\n')
  .map((line) => (line ? '  ' + line : line))
  .join('\n');
output.push(`
// ============================================================================
// Map Renderer Types (copied from mudlet-map-renderer)
// ============================================================================

export declare namespace MapRenderer {
${rendererSettingsBody}
}
`);

// MapData (rooms, areas) is an ambient global namespace in the client; the
// package has to export it, since a global would clash with the plugin's own.
const mapDataPath = path.join(PROJECT_ROOT, 'src', 'client', 'types', 'MapData.d.ts');
const mapData = fs.readFileSync(mapDataPath, 'utf-8').replace(/\r\n/g, '\n');
if (/^import /m.test(mapData) || !/^declare namespace MapData \{/m.test(mapData)) {
  console.error('❌ src/client/types/MapData.d.ts changed shape - update the MapData namespace inlining');
  process.exit(1);
}
output.push(`
// ============================================================================
// Map Data Types (from src/client/types/MapData.d.ts)
// ============================================================================

${mapData.trim().replace(/^declare namespace MapData \{/m, 'export declare namespace MapData {')}

// ============================================================================
// Internal Types
// ============================================================================

/**
 * The client instance handed to button and trigger macros. Internal and not
 * part of the plugin API - its shape may change between client versions.
 */
export type Client = any;
`);


output.push(`
// ============================================================================
// API Namespaces
// ============================================================================
`);

// API types and event types, with everything they reference
const roots = exportedTypeSymbols(sourceFile);
if (!roots.some((symbol) => symbolName(symbol) === 'PluginApi')) {
  console.error(`❌ PluginApi is not exported from ${path.relative(PROJECT_ROOT, SOURCE_FILE)}`);
  process.exit(1);
}
const eventsSourceFile = program.getSourceFile(EVENTS_FILE);
const clientEvents = eventsSourceFile?.statements.find((st) => ts.isTypeAliasDeclaration(st) && st.name.text === 'ClientEvents');
if (!clientEvents) {
  console.error(`❌ ClientEvents not found in ${path.relative(PROJECT_ROOT, EVENTS_FILE)}`);
  process.exit(1);
}
roots.push(checker.getSymbolAtLocation(clientEvents.name));
emitReachableTypes(roots, sourceFile);
if (problems.length) {
  console.error('❌ Some referenced types cannot be emitted:');
  for (const problem of problems) console.error(`   - ${problem}`);
  process.exit(1);
}

// Add final exports
output.push(`
// ============================================================================
// Exports
// ============================================================================

export default PluginApi;
`);

// Write output file
const finalOutput = output.join('\n');
fs.writeFileSync(OUTPUT_FILE, finalOutput, 'utf-8');

// The package must compile on its own: a name it uses but never declares turns
// into `any` for plugins (skipLibCheck hides it), which is how types went missing.
const UI_TYPES_FILE = path.join(__dirname, 'ui.d.ts');
const check = ts.createProgram({
  rootNames: [OUTPUT_FILE, UI_TYPES_FILE],
  options: {
    noEmit: true,
    strict: true,
    target: ts.ScriptTarget.ES2022,
    lib: ['lib.es2022.d.ts', 'lib.dom.d.ts', 'lib.dom.iterable.d.ts'],
    types: ['react'],
    typeRoots: [path.join(PROJECT_ROOT, 'node_modules', '@types')],
    module: ts.ModuleKind.ESNext,
    moduleResolution: ts.ModuleResolutionKind.Bundler,
    paths: { '@arkadia/plugin-types': [OUTPUT_FILE] },
  },
});
const checkDiagnostics = ts.getPreEmitDiagnostics(check)
  .filter((d) => d.file && [OUTPUT_FILE, UI_TYPES_FILE].includes(path.resolve(d.file.fileName)));
if (checkDiagnostics.length) {
  console.error(`❌ ${path.relative(PROJECT_ROOT, OUTPUT_FILE)} does not compile:`);
  console.error(ts.formatDiagnostics(checkDiagnostics, {
    getCanonicalFileName: (f) => f,
    getCurrentDirectory: () => PROJECT_ROOT,
    getNewLine: () => '\n',
  }));
  process.exit(1);
}

// The host-UI shim used by esbuild.cjs is compiled from the same module the
// client's editor bundler uses, so both map react/@arkadia/ui identically.
const SHIM_SOURCE = path.join(PROJECT_ROOT, 'src', 'shared', 'pluginUiGlobal.ts');
const SHIM_OUTPUT = path.join(__dirname, 'pluginUiShim.cjs');
const shim = ts.transpileModule(fs.readFileSync(SHIM_SOURCE, 'utf-8'), {
  compilerOptions: { module: ts.ModuleKind.CommonJS, target: ts.ScriptTarget.ES2020 },
});
fs.writeFileSync(SHIM_OUTPUT, `// AUTO-GENERATED from src/shared/pluginUiGlobal.ts by generate-types.cjs\n${shim.outputText}`, 'utf-8');
console.log(`📝 Shim: ${path.relative(PROJECT_ROOT, SHIM_OUTPUT)}`);

console.log('✅ Type definitions generated successfully!');
console.log(`📦 Exported ${exportedTypes.size} type definitions`);
console.log(`📏 Output size: ${(finalOutput.length / 1024).toFixed(2)} KB`);
